static const fcn16_g_t *fcn16_find(unsigned cp) {
    int lo = 0, hi = (int)FCN16_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        unsigned m = fcn16_dir[mid].cp;
        if (m == cp) return &fcn16_dir[mid];
        if (m < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
static void fcn16_glyph(int x, int y, const fcn16_g_t *g, uint32_t fg) {
    fg = fb_map(fg);
    const unsigned char *bm = fcn16_bits + g->off;
    int gx = x + g->xo, gy = y + g->yo;
    int idx = 0;
    for (int r = 0; r < g->h; r++) {
        for (int c = 0; c < g->w; c++) {
            unsigned a = (idx & 1) ? (bm[idx >> 1] & 0xF) : (bm[idx >> 1] >> 4);
            idx++;
            if (a) fcn_blend(gx + c, gy + r, a, fg);
        }
    }
}
static int fcn16_text(int x, int y, const char *s, uint32_t fg) {
    while (*s) {
        unsigned cp;
        int n = utf8_dec((const unsigned char *)s, &cp);
        const fcn16_g_t *g = fcn16_find(cp);
        if (g) { fcn16_glyph(x, y, g, fg); x += g->adv; }
        else if (cp < 0x80 && cp >= ' ') { x += FCN16_PX / 2; }
        s += n;
    }
    return x;
}
static int fcn16_w(const char *s) {
    int x = 0;
    while (*s) {
        unsigned cp;
        int n = utf8_dec((const unsigned char *)s, &cp);
        const fcn16_g_t *g = fcn16_find(cp);
        x += g ? g->adv : (cp < 0x80 && cp >= ' ' ? FCN16_PX / 2 : 0);
        s += n;
    }
    return x;
}
static void fcn16_center(int cx, int y, const char *s, uint32_t fg) {
    fcn16_text(cx - fcn16_w(s) / 2, y, s, fg);
}

